import re

_TOKEN_RE = re.compile(r'-?\d+|\S+')
_NUMBER_RE = re.compile(r'-?\d+')


class StackUnderflowError(Exception):
    pass


def _tokenize(line):
    return _TOKEN_RE.findall(line)


def _is_number(token):
    return bool(_NUMBER_RE.fullmatch(token))


def _pop(stack):
    if not stack:
        raise StackUnderflowError("Insufficient number of items in stack")
    return stack.pop()


def _add(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(a + b)


def _sub(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(a - b)


def _mul(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(a * b)


def _div(stack):
    b = _pop(stack)
    a = _pop(stack)
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    quotient = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        quotient = -quotient
    stack.append(quotient)


def _dup(stack):
    if not stack:
        raise StackUnderflowError("Insufficient number of items in stack")
    stack.append(stack[-1])


def _drop(stack):
    _pop(stack)


def _swap(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(a)
    stack.append(b)


def _over(stack):
    if len(stack) < 2:
        raise StackUnderflowError("Insufficient number of items in stack")
    stack.append(stack[-2])


BUILTINS = {
    '+': _add,
    '-': _sub,
    '*': _mul,
    '/': _div,
    'dup': _dup,
    'drop': _drop,
    'swap': _swap,
    'over': _over,
}


def _expand(tokens, definitions):
    """Expand user-defined words in a definition body at definition time."""
    expanded = []
    for token in tokens:
        word = token.lower()
        if not _is_number(token) and word in definitions:
            expanded.extend(definitions[word])
        else:
            expanded.append(token)
    return expanded


def _exec_token(token, stack):
    if _is_number(token):
        stack.append(int(token))
    else:
        builtin = BUILTINS.get(token.lower())
        if builtin is None:
            raise ValueError("undefined operation")
        builtin(stack)


def evaluate(input_data):
    stack = []
    definitions = {}
    for line in input_data:
        tokens = _tokenize(line)
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token == ':':
                name = tokens[i + 1].lower()
                if _is_number(name):
                    raise ValueError("illegal operation")
                j = i + 2
                while tokens[j] != ';':
                    j += 1
                definitions[name] = _expand(tokens[i + 2:j], definitions)
                i = j + 1
            else:
                word = token.lower()
                if word in definitions:
                    for body_token in definitions[word]:
                        _exec_token(body_token, stack)
                elif _is_number(token):
                    stack.append(int(token))
                elif word in BUILTINS:
                    BUILTINS[word](stack)
                else:
                    raise ValueError("undefined operation")
                i += 1
    return stack

